$:node <<'NODE'
const {spawn}=require('node:child_process');
const requests=[
 {name:'small',target_url:'https://chatgpt.com/share/6ae6b576-9fa8-83e8-a040-4091fe0218e3'},
 {name:'large',target_url:'https://chatgpt.com/share/6ae9dd85-7ff0-83e8-90c3-4592305a2362'}
];
const dispatch=r=>new Promise(resolve=>{
 const payload=JSON.stringify({target_url:r.target_url,request_id:'e2e008-distinct-'+r.name+'-20261103',export_profile:'complete'});
 const p=spawn('gh',['workflow','run','chatgpt-shared-conversation-extractor.yml','--repo','BestNameYet/Terminals','--ref','main','--raw-field','request_json='+payload]);
 let stdout='',stderr='';
 p.stdout.on('data',c=>stdout+=c);p.stderr.on('data',c=>stderr+=c);
 p.on('close',code=>resolve({share:r.name,status:code,run_url:stdout.trim(),error:stderr.trim()}));
 p.on('error',e=>resolve({share:r.name,status:-1,error:e.message}));
});
Promise.all(requests.map(dispatch)).then(r=>{
 for(const x of r)console.log(JSON.stringify(x));
 if(r.some(x=>x.status!==0))process.exitCode=1;
});
